import { envGet } from "../_shared/env";
import * as zlib from "node:zlib";
import { Buffer } from "node:buffer";
import { createClient } from "@supabase/supabase-js";

const B64="";
let CACHE:any=null;
const JOURNEYS=[
 {slug:"state-borders-sovereignty",ne:"सीमा, सार्वभौमिकता र विश्वसँग नेपाल",en:"Borders, sovereignty and Nepal in the world",ids:["NTL-E-000099","NTL-E-000059","NTL-E-000234","NTL-E-000061","NTL-E-000062","NTL-E-000110","NTL-E-000003"]},
 {slug:"rana-rule-resistance-reform",ne:"राणा शासन, प्रतिरोध र परिवर्तन",en:"Rana rule, resistance and reform",ids:["NTL-E-000001","NTL-E-000002","NTL-E-000031","NTL-E-000057","NTL-E-000063","NTL-E-000064","NTL-E-000144","NTL-E-000150","NTL-E-000113"]},
 {slug:"democracy-panchayat-multiparty",ne:"प्रजातन्त्रदेखि पञ्चायत र बहुदलसम्म",en:"Democracy, Panchayat and multiparty politics",ids:["NTL-E-000015","NTL-E-000153","NTL-E-000016","NTL-E-000017","NTL-E-000513","NTL-E-000038","NTL-E-000039","NTL-E-000040","NTL-E-000041"]},
 {slug:"conflict-peace-republic-constitution",ne:"द्वन्द्व, शान्ति, गणतन्त्र र संविधान",en:"Conflict, peace, republic and constitution",ids:["NTL-E-000005","NTL-E-000008","NTL-E-000025","NTL-E-000026","NTL-E-000028","NTL-E-000010","NTL-E-000012","NTL-E-000011","NTL-E-000013"]},
 {slug:"rights-representation",ne:"अधिकार र प्रतिनिधित्वका मोडहरू",en:"Rights and representation",ids:["NTL-E-000063","NTL-E-000064","NTL-E-000564","NTL-E-000565","NTL-E-000230","NTL-E-000229","NTL-E-000108","NTL-E-000037","NTL-E-000021"]}
];

function data(){if(!CACHE)CACHE=JSON.parse(zlib.gunzipSync(Buffer.from(B64,"base64")).toString("utf8"));return CACHE}

let ARCHIVE_CACHE:any=null;
let MERGED_CACHE:any=null;
const ARCHIVE_TTL=5*60*1000;

function tmAdmin(){
 const url=envGet("SUPABASE_URL")||"";
 let key=envGet("SUPABASE_SERVICE_ROLE_KEY")||"";
 if(!key){try{key=JSON.parse(envGet("SUPABASE_SECRET_KEYS")||"{}").default||""}catch{}}
 return url&&key?createClient(url,key,{auth:{persistSession:false}}):null;
}
function cleanText(s:any){return String(s||"").normalize("NFC").toLowerCase().replace(/[^\p{L}\p{M}\p{N}]+/gu," ").trim().replace(/\s+/g," ")}
function parseBsDate(v:any){const m=String(v||"").match(/(\d{4})-(\d{1,2})-(\d{1,2})/);return m?{y:+m[1],m:+m[2],d:+m[3]}:{y:null,m:null,d:null}}
function sourceArray(r:any){
 const a=Array.isArray(r.sources)?r.sources.filter((s:any)=>s&&typeof s==="object"):[];
 if(a.length)return a;
 return r.source_name||r.source_url?[{title:r.source_name||"Source",url:r.source_url||"",source_id:r.source_record_id||""}]:[];
}
function archiveToEvent(r:any){
 const bs=parseBsDate(r.bs_date),src=sourceArray(r);
 const np=r.country_code==="NP"||String(r.country||"").toLowerCase()==="nepal";
 return {
  event_id:"OTD-"+r.id,
  ad_year:r.ad_year,ad_month:r.ad_month,ad_day:r.ad_day,
  ad_date_start:r.ad_date||([r.ad_year,r.ad_month,r.ad_day].every((x:any)=>x!=null)?String(r.ad_year)+"-"+String(r.ad_month).padStart(2,"0")+"-"+String(r.ad_day).padStart(2,"0"):null),
  ad_date_precision:r.event_date_precision||"day",
  bs_date_start:r.bs_date||"",bs_year:bs.y,bs_month:bs.m,bs_day:bs.d,
  title_ne:r.title_ne||"",title_en:r.title_en||"",
  short_summary_ne:r.summary_ne||"",short_summary_en:r.summary_en||"",
  historical_significance_ne:"",historical_significance_en:"",
  controversy_or_uncertainty_ne:"",controversy_or_uncertainty_en:"",
  category:r.category||r.event_type||"history",
  era:"archive",importance_nepal:r.importance??50,
  verification_status:r.verification_status||"unverified",
  confidence_score:null,
  sources:src,source_count:src.length,
  locality:"",district:"",province:"",country:r.country||"",
  image_url:r.image_url||"",image_caption_ne:r.image_caption_ne||"",image_caption_en:r.image_caption_en||"",
  image_credit:r.image_credit||"",image_license:r.image_license||"",
  event_type:r.event_type||"event",highlight:!!r.highlight,
  _layer:"archive",_scope:np?"nepal":"world",_source_record_id:r.source_record_id||""
 };
}
function curatedEvents(){
 return data().events.map((e:any)=>({...e,_layer:"curated",_scope:"nepal"}));
}
async function archiveEvents(){
 const now=Date.now();
 if(ARCHIVE_CACHE&&now-ARCHIVE_CACHE.at<ARCHIVE_TTL)return ARCHIVE_CACHE.events;
 const db=tmAdmin(); if(!db)return [];
 const fields="id,ad_year,ad_month,ad_day,ad_date,bs_date,title_ne,title_en,summary_ne,summary_en,category,source_name,source_url,event_date_precision,verification_status,importance,sources,metadata,source_record_id,event_type,country_code,country,highlight,image_url,image_caption_ne,image_caption_en,image_credit,image_license";
 const out:any[]=[]; const page=1000;
 for(let from=0;;from+=page){
  const {data:rows,error}=await db.from("on_this_day_events").select(fields).eq("published",true).order("id",{ascending:true}).range(from,from+page-1);
  if(error)throw error;
  const got=rows||[];out.push(...got.map(archiveToEvent));
  if(got.length<page)break;
 }
 ARCHIVE_CACHE={at:now,events:out}; return out;
}
function eventKey(e:any){
 const y=e.ad_year??"",m=e.ad_month??"",d=e.ad_day??"";
 return y+"-"+m+"-"+d+"|"+cleanText(e.title_en||e.title_ne);
}
async function mergedEvents(){
 const now=Date.now();
 if(MERGED_CACHE&&now-MERGED_CACHE.at<ARCHIVE_TTL)return MERGED_CACHE;
 const curated=curatedEvents(); let archive:any[]=[]; let archiveError="";
 try{archive=await archiveEvents()}catch(e:any){archiveError=String(e?.message||e)}
 const seen=new Set(curated.map(eventKey)); const deduped:any[]=[];
 for(const e of archive){const k=eventKey(e);if(k&&seen.has(k))continue;if(k)seen.add(k);deduped.push(e)}
 const events=[...curated,...deduped].sort((a:any,b:any)=>(a.ad_year??999999)-(b.ad_year??999999)||(a.ad_month??0)-(b.ad_month??0)||(a.ad_day??0)-(b.ad_day??0));
 const counts={
  total:events.length,curated:curated.length,archive:deduped.length,
  nepal:events.filter((e:any)=>e._scope==="nepal").length,
  world:events.filter((e:any)=>e._scope==="world").length,
  source_backed:events.filter((e:any)=>/^(verified|official|cross-checked|source-backed)/.test(String(e.verification_status||""))).length
 };
 MERGED_CACHE={at:now,events,counts,archiveError}; return MERGED_CACHE;
}
function compact(e:any){return {
 id:e.event_id,ad:e.ad_date_start||String(e.ad_year||""),ay:e.ad_year,am:e.ad_month,adn:e.ad_day,
 bs:e.bs_date_start||"",by:e.bs_year,bm:e.bs_month,bd:e.bs_day,
 tne:e.title_ne,ten:e.title_en,sne:e.short_summary_ne,sen:e.short_summary_en,
 era:e.era||"archive",category:e.category,importance:e.importance_nepal,
 verification:e.verification_status,confidence:e.confidence_score,precision:e.ad_date_precision,
 disputed:!!(e.controversy_or_uncertainty_ne||e.controversy_or_uncertainty_en),
 layer:e._layer||"curated",scope:e._scope||"nepal",type:e.event_type||"event",
 country:e.country||"",sourceCount:e.source_count||0,highlight:!!e.highlight
}}
function json(x:any,status=200,cache="public, max-age=120, s-maxage=300, stale-while-revalidate=1800"){return new Response(JSON.stringify(x),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":cache}})}
export async function timeMachineApi(path:string,u:URL){
 const merged=await mergedEvents(),all=merged.events;
 if(path==="/api/time-machine/bootstrap"){
  const eras:any={};for(const e of all){const k=e.era||"archive";eras[k]=(eras[k]||0)+1}
  const adYears=all.filter((e:any)=>Number.isFinite(e.ad_year)).map((e:any)=>e.ad_year);
  const bsYears=all.filter((e:any)=>Number.isFinite(e.bs_year)).map((e:any)=>e.bs_year);
  return json({ok:true,build:"v50-unified-history",total:all.length,published_only:true,counts:merged.counts,archive_error:merged.archiveError||null,range:{ad:[Math.min(...adYears),Math.max(...adYears)],bs:bsYears.length?[Math.min(...bsYears),Math.max(...bsYears)]:[null,null]},eras,journeys:JOURNEYS.map(j=>({...j,count:j.ids.length,ids:undefined}))});
 }
 if(path==="/api/time-machine/events"){
  const from=Number(u.searchParams.get("from")||-99999),to=Number(u.searchParams.get("to")||99999),era=u.searchParams.get("era")||"",cat=u.searchParams.get("category")||"",verify=u.searchParams.get("verification")||"",layer=u.searchParams.get("layer")||"",scope=u.searchParams.get("scope")||"",q=(u.searchParams.get("q")||"").trim().toLowerCase(),limit=Math.min(7000,Math.max(1,Number(u.searchParams.get("limit"))||120)),offset=Math.max(0,Number(u.searchParams.get("offset"))||0);
  const rows=all.filter((e:any)=>(e.ad_year||-99999)>=from&&(e.ad_year||99999)<=to&&(!era||e.era===era)&&(!cat||e.category===cat)&&(!verify||e.verification_status===verify)&&(!layer||e._layer===layer)&&(!scope||e._scope===scope)&&(!q||cleanText([e.title_ne,e.title_en,e.short_summary_ne,e.short_summary_en,e.country,e.category].join(" ")).includes(cleanText(q))));
  return json({ok:true,total:rows.length,offset,limit,items:rows.slice(offset,offset+limit).map(compact)});
 }
 if(path.startsWith("/api/time-machine/event/")){const id=decodeURIComponent(path.split("/").pop()||""),e=all.find((x:any)=>x.event_id===id);return e?json({ok:true,event:e}):json({error:"not_found"},404)}
 if(path==="/api/time-machine/surprise"){const verified=u.searchParams.get("highly_verified")==="true",pool=verified?all.filter((e:any)=>/^(verified|official|cross-checked|source-backed)/.test(String(e.verification_status||""))):all;const seed=Number(u.searchParams.get("seed"))||Date.now();return pool.length?json({ok:true,event:compact(pool[Math.abs(seed)%pool.length])}):json({error:"empty"},404)}
 if(path==="/api/time-machine/on-this-day"){const cal=u.searchParams.get("calendar")==="bs"?"bs":"ad",m=Number(u.searchParams.get("month")),d=Number(u.searchParams.get("day"));const rows=all.filter((e:any)=>cal==="bs"?e.bs_month===m&&e.bs_day===d:e.ad_month===m&&e.ad_day===d);return json({ok:true,calendar:cal,month:m,day:d,total:rows.length,items:rows.map(compact)})}
 if(path==="/api/time-machine/journeys"){const curated=curatedEvents();return json({ok:true,items:JOURNEYS.map(j=>({...j,events:j.ids.map(id=>curated.find((e:any)=>e.event_id===id)).filter(Boolean).map(compact)}))})}
 return null;
}

